  "java/java-concurrency": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        Scanner s = new Scanner(System.in);\n        int n = s.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = s.nextLong();\n        int m = n / 2;\n        long[] p = new long[2];\n        Thread t1 = new Thread(() -> {\n            long x = 0;\n            for (int i = 0; i < m; i++) x += v[i];\n            p[0] = x;\n        });\n        Thread t2 = new Thread(() -> {\n            long x = 0;\n            for (int i = m; i < n; i++) x += v[i];\n            p[1] = x;\n        });\n        t1.start();\n        t2.start();\n        t1.join();\n        t2.join();\n        System.out.println(p[0] + p[1]);\n    }\n}",
  "java/java-data-structures": "import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.hasNextLine() ? sc.nextLine().trim() : \"\";\n        char[] stack = new char[s.length() + 1];\n        int top = 0;\n        boolean ok = true;\n        for (int i = 0; i < s.length() && ok; i++) {\n            char c = s.charAt(i);\n            if (c == '(' || c == '[' || c == '{') {\n                stack[top++] = c;\n            } else {\n                char need;\n                if (c == ')') need = '(';\n                else if (c == ']') need = '[';\n                else need = '{';\n                if (top == 0 || stack[top - 1] != need) {\n                    ok = false;\n                } else {\n                    top--;\n                }\n            }\n        }\n        if (top != 0) ok = false;\n        System.out.println(ok ? \"YES\" : \"NO\");\n    }\n}",
  "java/java-generics-collections": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Map<String, Integer> counts = new HashMap<>();\n        for (int i = 0; i < n; i++) {\n            String w = sc.next();\n            counts.merge(w, 1, Integer::sum);\n        }\n        List<Map.Entry<String, Integer>> list = new ArrayList<>(counts.entrySet());\n        list.sort((a, b) -> {\n            int c = Integer.compare(b.getValue(), a.getValue());\n            return c != 0 ? c : a.getKey().compareTo(b.getKey());\n        });\n        StringBuilder sb = new StringBuilder();\n        for (Map.Entry<String, Integer> e : list) {\n            sb.append(e.getKey()).append(' ').append(e.getValue()).append('\\n');\n        }\n        System.out.print(sb);\n    }\n}\n",
